// POST /api/stories/:id/respond  替他去拍：上传现场新照与寄语
func Respond(db *gorm.DB) gin.HandlerFunc {
	return func(c *gin.Context) {
		var req respondReq
		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "请上传现场照片并写下寄语"})
			return
		}
		me := currentUser(c)
		storyID := c.Param("id")
