			auth.GET("/my/responses", handlers.MyResponses(db))
			auth.GET("/my/transactions", handlers.MyTransactions(db))
		}
	}

	log.Printf("记忆连接后端已启动: http://localhost:%s", cfg.Port)
	if err := r.Run(":" + cfg.Port); err != nil {
		log.Fatal(err)
	}
}

