input.content:
:root {
  --bg: #f6f1e7;
  --paper: #fffdf7;
  --ink: #3d3428;
  --muted: #8a7d68;
  --accent: #c96f4a;
  --accent-dark: #a85434;
  --gold: #d9a441;
  --line: #e5dcc8;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans SC", sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.6;
}

.container { max-width: 880px; margin: 0 auto; padding: 24px 16px 64px; }

/* 顶栏 */
.topbar {
  position: sticky; top: 0; z-index: 10;
  display: flex; align-items: center; gap: 24px;
  padding: 12px 24px;
  background: rgba(255, 253, 247, 0.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: 10px; cursor: pointer; }
.logo { font-size: 28px; }
.brand-name { font-size: 18px; font-weight: 700; letter-spacing: 2px; }
.slogan { font-size: 12px; color: var(--muted); }
.topbar nav { display: flex; gap: 16px; flex: 1; }
.nav-link { color: var(--muted); text-decoration: none; font-size: 15px; }
.nav-link.router-link-active { color: var(--accent); font-weight: 600; }
.auth-area { display: flex; align-items: center; gap: 10px; }
.nickname { font-weight: 600; }
.coin-badge {
  background: #fdf3dd; border: 1px solid #eed9a4; color: #8a6d1f;
  border-radius: 999px; padding: 3px 12px; font-size: 13px; font-weight: 600;
}
.coin-badge em { font-style: normal; font-weight: 400; color: var(--muted); }

/* 按钮 */
.btn {
  border: none; border-radius: 8px; padding: 8px 18px;
  font-size: 14px; cursor: pointer; transition: all .15s;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-dark); }
.btn-ghost { background: transparent; border: 1px solid var(--line); color: var(--muted); }
.btn-ghost:hover { border-color: var(--accent); color: var(--accent); }
.btn-gold { background: var(--gold); color: #fff; }
.btn-gold:hover { filter: brightness(0.95); }
.btn:disabled { opacity: .5; cursor: not-allowed; }
.btn-sm { padding: 4px 12px; font-size: 13px; }

/* 卡片 */
.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 20px;
  margin-bottom: 18px;
  box-shadow: 0 2px 10px rgba(93, 74, 45, 0.06);
}

/* 表单 */
.field { margin-bottom: 14px; }
.field label { display: block; font-size: 13px; color: var(--muted); margin-bottom: 4px; }
.field input, .field textarea {
  width: 100%; padding: 9px 12px; font-size: 14px;
  border: 1px solid var(--line); border-radius: 8px;
  background: #fff; color: var(--ink); font-family: inherit;
}
.field input:focus, .field textarea:focus { outline: 2px solid rgba(201, 111, 74, .35); border-color: var(--accent); }
.field textarea { resize: vertical; min-height: 80px; }

/* 弹窗 */
.modal-mask {
  position: fixed; inset: 0; z-index: 100;
  background: rgba(61, 52, 40, .45);
  display: flex; align-items: center; justify-content: center;
  padding: 20px;
}
.modal {
  background: var(--paper); border-radius: 14px;
  width: 100%; max-width: 460px; max-height: 88vh; overflow-y: auto;
  padding: 24px;
}
.modal h3 { margin-bottom: 16px; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; }

/* 提示 */
.error-text { color: #b03a2e; font-size: 13px; margin-top: 8px; }
.empty { text-align: center; color: var(--muted); padding: 48px 0; }
.section-title { font-size: 17px; font-weight: 700; margin: 26px 0 14px; }

/* 照片 */
.photo {
  width: 100%; border-radius: 10px; object-fit: cover;
  background: #efe8d8; display: block;
}
.photo-placeholder {
  width: 100%; height: 100%; min-height: 160px;
  display: flex; align-items: center; justify-content: center;
  background: repeating-linear-gradient(45deg, #f3ecdc, #f3ecdc 12px, #ece2cc 12px, #ece2cc 24px);
  border-radius: 10px; color: var(--muted); font-size: 13px; text-align: center; padding: 12px;
}

/* 上传预览 */
.upload-box { display: flex; align-items: center; gap: 12px; }
.upload-box img { width: 84px; height: 84px; object-fit: cover; border-radius: 8px; }

/* 标签 */
.tag {
  display: inline-block; font-size: 12px; padding: 2px 10px;
  border-radius: 999px; font-weight: 600;
}
.tag-open { background: #e6f4ea; color: #2e7d32; }
.tag-settled { background: #fdf3dd; color: #8a6d1f; }
.tag-cancelled { background: #eee; color: #888; }
.tag-pending { background: #e8f0fe; color: #3367d6; }
.tag-accepted { background: #e6f4ea; color: #2e7d32; }
.tag-rejected { background: #eee; color: #888; }

/* 双面明信片 */
.postcard-wrap { perspective: 1400px; margin-top: 14px; }
.postcard {
  position: relative; width: 100%; min-height: 320px;
  transform-style: preserve-3d;
  transition: transform .7s cubic-bezier(.4, .1, .2, 1);
  cursor: pointer;
}
.postcard.flipped { transform: rotateY(180deg); }
.postcard-face {
  position: absolute; inset: 0;
  backface-visibility: hidden;
  border-radius: 12px; overflow: hidden;
  border: 1px solid var(--line);
  background: var(--paper);
  display: flex; flex-direction: column;
}
.postcard-face.back { transform: rotateY(180deg); }
.postcard-face .face-label {
  padding: 8px 14px; font-size: 12px; letter-spacing: 3px; font-weight: 700;
  color: #fff;
}
.face-label.past { background: #9c8465; }
.face-label.now { background: var(--accent); }
.postcard-face .face-body { padding: 14px; display: flex; gap: 14px; flex: 1; }
.postcard-face .face-photo { flex: 0 0 45%; }
.postcard-face .face-photo img { width: 100%; height: 100%; min-height: 180px; object-fit: cover; border-radius: 8px; }
.postcard-face .face-text { flex: 1; font-size: 14px; white-space: pre-wrap; }
.postcard-flip-hint { text-align: center; font-size: 12px; color: var(--muted); margin-top: 8px; }

@media (max-width: 640px) {
  .topbar { flex-wrap: wrap; gap: 8px; }
  .postcard-face .face-body { flex-direction: column; }
  .postcard { min-height: 480px; }
}

